import{_ as i,a0 as u,w as p,s as r,ao as d,I as a,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"每日Ubuntu小技巧  —— 讓Windows訪問你文件的最簡單的方法 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧  —— 讓Windows訪問你文件的最簡單的方法 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧  —— 讓Windows訪問你文件的最簡單的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧  —— 讓Windows訪問你文件的最簡單的方法 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Easiest Way To Access Your Files From Windows","title":"每日Ubuntu小技巧  —— 讓Windows訪問你文件的最簡單的方法","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Easiest Way To Access Your Files From Windows.md","filePath":"[post].md"}'),l={name:"201310/Daily Ubuntu Tips – Easiest Way To Access Your Files From Windows.md"};function m(b,t,w,T,g,f){const s=u("Link");return p(),r("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-——-讓windows訪問你文件的最簡單的方法" tabindex="-1">每日Ubuntu小技巧 —— 讓Windows訪問你文件的最簡單的方法 <a class="header-anchor" href="#每日ubuntu小技巧-——-讓windows訪問你文件的最簡單的方法" aria-label="Permalink to “每日Ubuntu小技巧  —— 讓Windows訪問你文件的最簡單的方法”">​</a></h1><p>不管你是一個新手還是精通Ubuntu和Windows的大牛，讓Windows訪問Ubuntu文件的最好的方式都是使用Samba。通過許多第三方工具可以很輕鬆的安裝和管理。</p><p>對於想要了解怎麼從Windows快速訪問Ubuntu文件的新用户或者新手來説，這篇短文將會告訴你該怎麼做。我們的目標是要幫助新用户。我們儘量將這篇教程寫得通俗易懂，以便讓新手看懂而不會遇到太大的困難。</p><p>在這裏我們不會太注重瞭解Samba是什麼或者怎麼將它配置加入域這類細節。我們要做的就是告訴你怎麼在Ubuntu中安裝和設置Samba，讓Windows可以訪問Ubuntu的文件。</p><p>如果你想要更多的瞭解Samba，我建議你Google一下，或者查詢下Wikipedia。首先在Ubuntu下打開你的終端，然後運行如下命令安裝Samba和其他相關的工具。</p><pre><code>sudo apt-get install samba cifs-utils
</code></pre><p>上面這條命令將會安裝Samba和其他相關的工具。在舊版的Ubuntu中，你可能需要使用<strong>smbfs</strong>替代cifs-utils。如果上面命令能夠使用就更好了。</p><p>然後，使用gedit（或者其他工具）打開Samba主配置文件，然後進行如下更改。可以使用如下命令打開主配置文件：</p><pre><code>sudo gedit /etc/samba/smb.conf
</code></pre><p>文件打開後，查找如下行並取消其註釋（刪掉行首的“;”）。它應該是這樣的：</p><pre><code>security = user
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/sambausersubuntu.png" alt=""></p><p>然後，向下滾動文件，找到下面這行，同時取消行首註釋。</p><pre><code>[homes]
</code></pre><p>這將會允許用户訪問訪問home目錄中的文件夾及文件。比如説，如果你 <strong>取消</strong> 註釋了[homes]，用户可以通過鍵入服務器名加用户名的方式訪問home目錄。</p><pre><code>\\\\192.168.0.2\\username
</code></pre><p>然後，運行如下命令向Samba資料庫添加你的賬户信息。這樣可以允許你使用Samba訪問共享文件。</p><pre><code>sudo smbpasswd -a usernmame
</code></pre><p>用你自己的用户名替代上述的username。</p><p>當提示創建密碼時，創建並確認即可。最後，重啓Samba服務或者重啓計算機。</p><p>通過Windows訪問文件時，點擊<strong>開始 –&gt; 運行</strong>然後輸入如下內容。或者打開資源管理器輸入如下內容，如圖。</p><pre><code>\\\\ubuntu_machine_IP\\username
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/sambausersubuntu1.png" alt=""></p><p>Enjoy!</p><hr>`,25)),a("p",null,[t[1]||(t[1]=e("來自: ",-1)),n(s,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-easiest-way-access-files-windows/"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-easiest-way-access-files-windows/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(s,{href:"https://github.com/scusjs"},{default:o(()=>[...t[2]||(t[2]=[e("SCUSJS",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const U=i(l,[["render",m]]);export{_ as __pageData,U as default};
